mapper.select:

where t.del_flag = '0'

    AND t.teacher_no like concat('%', #{teacherNo,jdbcType=VARCHAR}, '%')


    AND t.teacher_name like concat('%', #{teacherName,jdbcType=VARCHAR}, '%')


    AND t.teacher_type = #{teacherType}


    AND t.status = #{status}


    AND (
        t.dept_id = #{deptId} OR t.dept_id IN (
            SELECT x.dept_id FROM sys_dept x
            WHERE cast(#{deptId} as varchar) = any(string_to_array(x.ancestors, ','))
        )
        OR t.teacher_id IN (
            SELECT td.teacher_id FROM spas_teacher_dept td
            JOIN sys_dept xd ON xd.dept_id = td.dept_id
            WHERE td.dept_id = #{deptId}
               OR cast(#{deptId} as varchar) = any(string_to_array(xd.ancestors, ','))
        )
    )

${params.dataScope}
order by t.teacher_type asc, t.teacher_id desc


where t.del_flag = '0'
  and (
    (t.teacher_type = '1' and t.dept_id = #{deptId})
    or exists (
        select 1 from spas_teacher_dept td
        where td.teacher_id = t.teacher_id and td.dept_id = #{deptId}
    )
  )
order by t.teacher_name asc, t.teacher_id asc

mapper.insert:
insert into spas_teacher(
    teacher_no, teacher_name, teacher_type, dept_id, homeroom_dept_id, user_id, mobile, gender, status, del_flag, create_by, create_time, remark
) values (
    #{teacherNo}, #{teacherName}, #{teacherType}, #{deptId}, #{homeroomDeptId}, #{userId}, #{mobile}, #{gender},
    coalesce(#{status}, '0'), '0', #{createBy}, now(), #{remark}
)

mapper.update:
update spas_teacher
teacher_name = #{teacherName}, teacher_type = #{teacherType}, dept_id = #{deptId}, mobile = #{mobile}, gender = #{gender}, status = #{status}, remark = #{remark}, update_by = #{updateBy}, update_time = now()
where teacher_id = #{teacherId}

update spas_teacher set del_flag = '2', update_time = now()
where teacher_id in
#{teacherId}
